import fs from "node:fs/promises";
import path from "node:path";
import proc from "node:process";
import cac from "cac";
    // ...
const cli = cac("workspaces-filter").version("0.4.3");
cli.command("<pattern> [...command]", "Select by package name or workspace directory", { allowUnknownOptions: true }).example("workspaces-filter . build   # run in all packages of all workspaces").example("workspaces-filter _ build   # because the '*' would not work").example("").example(`workspaces-filter '*preset*' build`).example(`workspaces-filter '*preset*' add foo-pkg`).example(`workspaces-filter '*preset*' add --dev typescript`).example("").example(`workspaces-filter './packages/foo' -- echo 'Hello, World!'`).example(`workspaces-filter './packages/*preset*' -- pwd`).example("").example(`workspaces-filter '*preset*' --print names`).example(`workspaces-filter '*preset*' --print json`).example(`workspaces-filter '*preset*' --print dirs`).example(``).option("--print <mode>", "Print the names/folders of selected packages, without running command").option("--cwd <dir>", "Current working directory", { default: proc.cwd() }).option("--pm, --package-manager <pm>", "The package manager to use. Defaults to packageManager from root package.json, or Bun").action(async (pattern, command, options) => {
	const opts = { ...options };
	if (opts["--"].length === 0 && command.length === 0 && !opts.print) {
		cli.outputHelp();
		return;
	}
	const flags = { ...options };
	delete flags.print;
	delete flags.cwd;
	delete flags.pm;
	delete flags["package-manager"];
	delete flags.packageManager;
	const flagged = dargs(flags, { useEquals: false });
	if (flagged[0] === "--") {
		flagged.shift();
	}
	const rootPkgJson = JSON.parse(await fs.readFile(path.join(opts.cwd, "package.json"), "utf-8"));
	opts.packageManager = opts.packageManager || rootPkgJson.packageManager?.split("@") || "bun";
	opts.pm = opts.packageManager;
	opts.isShell = command.length === 0;
	let workspaces = rootPkgJson.workspaces;
	if (opts.packageManager === "pnpm") {
		const yamlParse = await import("yaml").then(({ parse }) => parse);
		const wsfileStr = await fs.readFile(path.join(opts.cwd, "pnpm-workspace.yaml"), "utf-8");
		const wsfile = yamlParse(wsfileStr);
		workspaces = wsfile.packages;
	}
	if (opts.help) {
		cli.outputHelp();
		return;
	}
	pattern = pattern === "." || pattern === "_" ? workspaces : pattern;
	const selected = await filter(workspaces, pattern, opts.cwd);
	if (opts.print) {
		if (opts.print === "json") {
			return console.log(JSON.stringify(selected));
		}
		if (opts.print === "names") {
			return console.log(Object.keys(selected).join("\n"));
		}
		if (opts.print === "dirs") {
			return console.log(Object.values(selected).reduce((acc, x) => acc.concat(x.dir), []).join("\n"));
		}
		return;
	}
	if (Object.keys(selected).length === 0) {
		console.log("No packages matching the filter.");
		return proc.exit(0);
	}
	await runCommandOn(opts.isShell ? flagged : command.concat(flagged).flat(), selected, opts);
});

